// src/provisioning.ts
function isActiveProfile(attributes, type) {
  return attributes.profileState === "ACTIVE" && (type ? attributes.profileType === type : true);
}
async function downloadActiveProvisioningProfiles(privateKey, issuerId, privateKeyId, bundleId, profileType) {
  const client2 = createClient2({ privateKey, issuerId, privateKeyId });
  const { data: bundleIds } = await bundleIdsGetCollection({
    client: client2,
    throwOnError: true,
    query: {
      "filter[identifier]": [bundleId],
      include: ["profiles"]
    }
  });
  if (bundleIds.data.length <= 0) {
    throw new Error(`No applications found with bundle id '${bundleId}'.`);
  }
  const profileIds = bundleIds.data.filter((value) => value.attributes?.identifier === bundleId).flatMap((bundle) => bundle.relationships?.profiles?.data ?? []).map((data) => data.id);
  const profiles = bundleIds.included?.filter(
    (i) => i.type === "profiles" && profileIds.includes(i.id) && i.attributes !== void 0 && isActiveProfile(i.attributes, profileType)
  );
  if (!(profiles && profiles.length > 0)) {
    throw new Error(
      `Unable to find 'ACTIVE' profiles for bundleId '${bundleId}'.`
    );
  }
  return profiles;
}

// src/main.ts
async function run() {
  try {
    const bundleId = getInput("bundle-id");
    const apiKeyId = getInput("api-key-id");
    const apiPrivateKey = getInput("api-private-key");
    const issuerId = getInput("issuer-id");
    const profileType = getInput("profile-type");
    const profiles = await downloadActiveProvisioningProfiles(
      apiPrivateKey,
      issuerId,
      apiKeyId,
      bundleId,
      profileType
    );
    if (!process.env.HOME) {
      throw new Error("Environment variable `HOME` is not defined!");
    }
    const profilesDir = join(
      process.env["HOME"],
      "Library/Developer/Xcode/UserData/Provisioning Profiles"
    );
    await mkdirP(profilesDir);
    for (const profile of profiles) {
      if (!(profile.attributes.uuid && profile.attributes.profileContent)) {
        throw new Error(
          "Profile attributes `uuid` and `profileContent` must be defined!"
        );
      }
      const filename = profileFilename(
        profile.attributes.uuid,
        profile.attributes
      );
      const buffer = Buffer.from(profile.attributes.profileContent, "base64");
      const fullPath = join(profilesDir, filename);
      writeFileSync(fullPath, buffer);
      info(
        `Wrote ${profile.attributes.profileType} profile '${profile.attributes.name}' to '${fullPath}'.`
      );
    }
    const outputProfiles = profiles.map((value) => {
      return {
        name: value.attributes.name,
        udid: value.attributes.uuid,
        type: value.attributes.profileType?.toString()
      };
    });
    setOutput("profiles", JSON.stringify(outputProfiles));
  } catch (error3) {
    setFailed(formatError(error3));
  }
}
run();
